#include <stdio.h>
#include <stdlib.h>

int main(void)
{
    int *p = calloc(4, sizeof(int));

    printf("%d%d%d%d\n", p[0], p[1], p[2], p[3]);
    free(p);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void)
{
    int *p = malloc(2 * sizeof(int));

    p[0] = 1;
    p[1] = 2;
    p = realloc(p, 4 * sizeof(int));
    p[2] = 3;
    p[3] = 4;
    printf("%d%d%d%d\n", p[0], p[1], p[2], p[3]);
    free(p);
    return 0;
}
